 148	export function expectedGet404Outcome(
 149		endpoint: string,
 150		method: string,
 151		status: number | undefined,
 152		page?: number,
 153	): ExpectedGet404Outcome | undefined {
 154		if (status !== 404 || method.toUpperCase() !== "GET") return undefined;
